sys_ui_action.client_script_v2:
// A Function for the Refresh Holdings Data button on the task table. On Click of Button it calls the Get Swift Data UI Action.
// A call is made to PositionDataForTask which Glide Records to Task Table and trigger 'el_custody_detail_position_ondemand' event.


function executePositionTaskEvent() {

    var positionattributeSync = g_form.getValue("position_attribute_sync");
    var taskSysId = g_form.getUniqueValue();
    var gajax = new GlideAjax("x_hsb11_mss_c_proc.getSwiftPosDataUIAction");
    gajax.addParam("sysparm_name", "PositionDataForTask");
    gajax.addParam("sysparm_id", taskSysId);
    gajax.addParam("sysparm_attribute_sync", positionattributeSync);

    gajax.getXMLAnswer(openList);
}

function openList(url) {
    if (url == "Attribute Sync is in progress") {
        g_form.addInfoMessage("Attribute Sync is already in progress");
    }
	else if (url == "security account or security id is empty") {
        g_form.addErrorMessage("Holdings data sync was not completed due to missing security information.");
    }
}

sys_ui_action.script:
// A Function for the Refresh Holdings Data button on the task table. On Click of Button it calls the Get Swift Data UI Action.

// MSSOTIQUBE-2406
function executePositionTaskEvent() {

    var positionattributeSync = g_form.getValue("position_attribute_sync");
    var taskSysId = g_form.getUniqueValue();
	var trade_sys_id = g_form.getValue('trade_id');
    var gajax = new GlideAjax("x_hsb11_mss_custod.MSSCustodyOnDemandCallUtils");
    gajax.addParam("sysparm_name", "refreshPositionDataAPICallHoldingList");
	gajax.addParam('sysparm_id',trade_sys_id);
    gajax.addParam("sysparm_task_id", taskSysId);
    gajax.addParam("sysparm_attribute_sync", positionattributeSync);

    gajax.getXMLAnswer(openList);
}

function openList(url) {
    if (url == "Attribute Sync is in progress") {
        g_form.addInfoMessage("Attribute Sync is already in progress");
    }
	else if (url == "security account or security id is empty") {
        g_form.addErrorMessage("Holdings data sync was not completed due to missing security information.");
    }
}
